    10	export interface PostgresRecordRepository {
    11	  insert(record: StoredRecord): Promise<void>;
    12	  find(id: string): Promise<StoredRecord | undefined>;
    13	}
    14	
    15	export interface RedisRecordCache {
    16	  put(record: StoredRecord): Promise<void>;
    17	  find(id: string): Promise<StoredRecord | undefined>;
    18	}
