    20	export class RecordService {
    21	  constructor(
    22	    private readonly ids: IdGenerator,
    23	    private readonly repository: PostgresRecordRepository,
    24	    private readonly cache: RedisRecordCache,
    25	  ) {}
    26	
    27	  async create(input: RecordInput): Promise<StoredRecord> {
    28	    const record = { id: this.ids.generate(), payload: input.payload };
    29	    await this.repository.insert(record);
    30	    await this.cache.put(record);
    31	    return record;
    32	  }
    33	
    34	  async retrieve(id: string): Promise<StoredRecord | undefined> {
    35	    const cached = await this.cache.find(id);
    36	    if (cached) return cached;
    37	
    38	    const stored = await this.repository.find(id);
    39	    if (stored) await this.cache.put(stored);
    40	    return stored;
    41	  }
    42	}
